<?php
session_start(); require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../includes/audit.php'; require_once __DIR__ . '/../includes/consent.php'; requireRole('patient');
expireConsentRequests($pdo);
$patientQuery = $pdo->prepare('SELECT id FROM patients WHERE user_id = :user_id LIMIT 1'); $patientQuery->execute([':user_id' => $_SESSION['user_id']]); $patientId = (int) $patientQuery->fetchColumn();
$requestQuery = $pdo->prepare('SELECT cr.id, cr.purpose, cr.requested_data, cr.status, cr.requested_at, cr.expires_at, u.username AS requester FROM consent_requests cr JOIN users u ON u.id = cr.requested_by WHERE cr.patient_id = :patient_id ORDER BY cr.requested_at DESC'); $requestQuery->execute([':patient_id' => $patientId]); $requests = $requestQuery->fetchAll(PDO::FETCH_ASSOC); $pageTitle = 'Consent'; require __DIR__ . '/../includes/header.php';
?><div class="d-flex justify-content-between align-items-center mb-4"><div><p class="eyebrow">Privacy control</p><h1 class="h2">Consent Requests</h1></div></div><div class="card border-0 shadow-sm"><div class="card-body"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Requester</th><th>Purpose</th><th>Requested data</th><th>Expiry</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($requests as $request): ?><tr><td><?= e($request['requester']) ?></td><td><?= e($request['purpose']) ?></td><td><?= e($request['requested_data']) ?></td><td><?= e($request['expires_at'] ?? 'No expiry') ?></td><td><?= e($request['status']) ?></td><td><?php if (in_array($request['status'], ['pending', 'approved'], true)): ?><form method="post" action="process_consent.php" class="d-flex gap-1"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><input type="hidden" name="request_id" value="<?= (int) $request['id'] ?>"><select class="form-select form-select-sm" name="decision" required><option value="">Action</option><?php if ($request['status'] === 'pending'): ?><option value="approved">Approve</option><option value="denied">Deny</option><?php else: ?><option value="revoked">Revoke</option><?php endif; ?></select><button class="btn btn-sm btn-primary">Apply</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if (!$requests): ?><tr><td colspan="6" class="text-muted">No consent requests.</td></tr><?php endif; ?></tbody></table></div></div></div><?php require __DIR__ . '/../includes/footer.php'; ?>